args.CommandLine:
"$brain_dir = "C:\Users\renu5\.gemini\antigravity\brain\8b5897f7-951a-4b48-bf8b-17bedfbbee0a"
$repo_dir = "C:\Users\renu5\.gemini\antigravity\scratch\repo_export\daily-push"
$session_id = "8b5897f7-951a-4b48-bf8b-17bedfbbee0a"
$export_dir = "$repo_dir\session_$session_id"

mkdir -Force $export_dir | Out-Null

# Copy artifacts (any .md files in the brain root)
Get-ChildItem -Path $brain_dir -Filter "*.md" -File | Copy-Item -Destination $export_dir

# Copy scratch files if they exist
$scratch_dir = "$brain_dir\scratch"
if (Test-Path $scratch_dir) {
    Copy-Item -Path $scratch_dir -Destination "$export_dir\scratch" -Recurse -Force
}

# Copy logs/transcripts
$logs_dir = "$brain_dir\.system_generated\logs"
if (Test-Path $logs_dir) {
    mkdir -Force "$export_dir\logs" | Out-Null
    Get-ChildItem -Path $logs_dir -Filter "*.jsonl" -File | Copy-Item -Destination "$export_dir\logs"
}

# Generate a conversation.md from transcript
$transcript_file = "$logs_dir\transcript.jsonl"
$output_md = "$export_dir\conversation.md"
"# Conversation Transcript`r`n" | Out-File $output_md -Encoding UTF8

if (Test-Path $transcript_file) {
    Get-Content $transcript_file | ForEach-Object {
        $json = $_ | ConvertFrom-Json
        if ($json.type -eq "USER_INPUT") {
            "**User**: " + $json.content + "`r`n`r`n" | Out-File $output_md -Append -Encoding UTF8
        } elseif ($json.type -eq "PLANNER_RESPONSE") {
            "**Agent**: " + $json.content + "`r`n`r`n" | Out-File $output_md -Append -Encoding UTF8
        }
    }
}
Write-Output "Files prepared."
"
